import{_ as e,H as s,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"课前准备 | 搭建实验环境","description":"","frontmatter":{},"headers":[{"level":2,"title":"操作系统","slug":"操作系统","link":"#操作系统","children":[]},{"level":2,"title":"编译器","slug":"编译器","link":"#编译器","children":[]},{"level":2,"title":"搭建环境","slug":"搭建环境","link":"#搭建环境","children":[]},{"level":2,"title":"GitHub项目","slug":"github项目","link":"#github项目","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]}],"relativePath":"罗剑锋的C++实战笔记/课前准备-搭建实验环境.md","filePath":"罗剑锋的C++实战笔记/课前准备-搭建实验环境.md","lastUpdated":1779821799000}'),p={name:"罗剑锋的C++实战笔记/课前准备-搭建实验环境.md"};function i(l,a,o,r,c,u){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h1 id="课前准备-搭建实验环境" tabindex="-1">课前准备 | 搭建实验环境 <a class="header-anchor" href="#课前准备-搭建实验环境" aria-label="Permalink to &quot;课前准备 | 搭建实验环境&quot;">​</a></h1><p>你好，我是Chrono。</p><p>在开始正式的学习之前，我们需要先做一点准备工作——在自己的电脑上搭建出课程使用的实验环境。</p><p>我会给你推荐具体的操作系统、编译器，带你一步步搭建环境，还会给你分享我的 <a href="https://github.com/chronolaw/cpp_study" target="_blank" rel="noreferrer">GitHub链接</a>，之后课程里的所有代码，你都可以在这里找到。</p><h2 id="操作系统" tabindex="-1">操作系统 <a class="header-anchor" href="#操作系统" aria-label="Permalink to &quot;操作系统&quot;">​</a></h2><p>首先说一下操作系统。</p><p>目前流行的操作系统有三种：Windows、macOS和Linux。</p><p>Windows是应用得最广泛的一个系统了，是绝对的主流，但是，作为C++开发环境来说，Windows并不能算是首选。</p><p>一个原因是，Windows上的标准C++开发工具Visual Studio不是免费的，尽管它提供了可自由下载的社区版，但有各种限制（你可以看下社区版和其他版本的 <a href="https://visualstudio.microsoft.com/zh-hans/vs/compare/" target="_blank" rel="noreferrer">差异</a>），用来做实验还行，如果要用来开发正式的软件，就不是那么合适了。</p><p>另一个更重要的原因是，Windows现在已经不再是C++的“主战场”了，现在开发Windows程序，更多的是用C#、Java、TypeScript等其他语言，在Windows上写C++程序，很难有大的作为，会有种“英雄无用武之地”的感觉。</p><p>macOS是苹果的专用系统，比较“小众精英”，用户比较少。必须要承认，它是一个很高效易用的开发环境，但也有点“曲高和寡”，不是每个人都能有一台MacBook的。而且，macOS虽然也是UNIX，但它源自FreeBSD，内部结构、使用方式与Linux有一些差异。</p><p>macOS也有与Windows相同的问题，它的官方开发语言是Objective-C、Swift，几乎没有纯粹使用C++开发出的Mac应用。</p><p>所以， <strong>我建议你使用Linux操作系统</strong>，它是完全自由、免费的系统，不受任何人的控制，开发工具链非常完善，而且，目前差不多所有的商业网站的服务器（当然还有Android）上跑的都是Linux，而C++也正好能在开发后台应用服务方面大显身手，两者可谓是“绝配”。</p><h2 id="编译器" tabindex="-1">编译器 <a class="header-anchor" href="#编译器" aria-label="Permalink to &quot;编译器&quot;">​</a></h2><p>选好了Linux操作系统，接下来就要选择编译器了。</p><p>虽然C++20马上就要发布了，但现在C++标准的实际普及情况还是相当落后的。据我多年的观察，很多企业因为各式各样的原因，还在用着老旧的操作系统和编译器，别说C++20了，连C++17都很少用到。</p><p>所以，从应用现状出发，我不会使用那么“超前”的标准和编译器，而是选择更贴合实际、更“接地气”的编译器，让你在工作中能够立即用得上，不用苦等操作系统、编译器的升级。</p><p>好了，说一下我对编译器的要求： <strong>至少要支持C++11，支持到C++14最好，对再往上的17/20则不强求，在今后的课程中，也会尽量不涉及17/20里的特性</strong>。</p><p>把这几点要求落实到Linux上的默认编译器GCC，就是4.6或者是 4.8版本，越高越好。至于具体版本GCC对C++的支持程度，可以在它的 <a href="https://gcc.gnu.org/projects/cxx-status.html" target="_blank" rel="noreferrer">官网</a> 上找到。</p><p>GCC通常是和Linux系统绑定在一起的，选编译器也就相当于选择Linux的版本。</p><p>Linux也是版本众多，最常见的是 <strong>RedHat系的CentOS</strong> 和 <strong>Debian系的Ubuntu</strong>。</p><p>这两个被很多企业广泛采用，但CentOS通常比较“稳定”，更新较慢，像CentOS 6一直用的是GCC 4.4，CentOS 7也才是4.8，对C++标准的支持很不完善，极大地限制了C++能力的发挥。</p><p>所以， <strong>我建议使用的Linux操作系统是Ubuntu，最低版本是16.04</strong>。这个系统里的GCC版本是5.4，完美支持C++11/14。当然，你要是愿意安装更新的18.04、20.04也没有问题，它们里面的GCC版本更高，支持C++17，只不过有点“功能过剩”。</p><h2 id="搭建环境" tabindex="-1">搭建环境 <a class="header-anchor" href="#搭建环境" aria-label="Permalink to &quot;搭建环境&quot;">​</a></h2><p>确定了操作系统和编译器以后，该去哪里找一个这样的开发环境呢？</p><p>你的公司里或许就有现成的Linux服务器，可以直接登录上去用，但公司服务器的环境不一定满足刚才说的那几点要求，而且还得小心，别把系统搞乱了，所以，还是弄一个自己的实验环境最保险。</p><p>好在如今的虚拟技术非常成熟，只要安装一个虚拟机软件，再去Ubuntu官网下载一个光盘镜像，然后按部就班地点点鼠标就行了。</p><p>这里我选择的是免费的VirtualBox，版本任意，Ubuntu则是 <a href="http://releases.ubuntu.com/16.04/ubuntu-16.04.6-desktop-amd64.iso" target="_blank" rel="noreferrer">64位的桌面版</a>。至于它们俩具体的安装过程，网上有很多资料，而且我相信，即使没有资料，也难不倒你，所以我就不再多说了。</p><p>弄好VirtualBox和Ubuntu环境之后，还有一个小小的“收尾”步骤。</p><p>Linux系统里通常默认只有GCC，没有G++，所以还要再执行一个apt-get命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt-get install g++</span></span></code></pre></div><p>安装完成后，在命令行里敲一下“g++”命令，看一下它的版本号是否满足我们的要求：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g++ --version</span></span>
<span class="line"><span></span></span>
<span class="line"><span>g++ (Ubuntu 5.4.0-6ubuntu1~16.04.9) 5.4.0 20160609</span></span>
<span class="line"><span>Copyright (C) 2015 Free Software Foundation, Inc.</span></span></code></pre></div><h2 id="github项目" tabindex="-1">GitHub项目 <a class="header-anchor" href="#github项目" aria-label="Permalink to &quot;GitHub项目&quot;">​</a></h2><p>和之前的 <a href="https://time.geekbang.org/column/intro/100029001" target="_blank" rel="noreferrer">《透视HTTP协议》</a> 一样，我也在GitHub上为这个课程建立了一个项目： <a href="https://github.com/chronolaw/cpp_study" target="_blank" rel="noreferrer">cpp_study</a>，里面有很多示例代码和有用的资料链接，你可以在Linux环境里用“git clone”下载。</p><p>不过，说起来不怕你笑话，我写了二十来年的C++程序，但一直不怎么会写Makefile。都说写Makefile是C++程序员的“基本功”，但我在这方面的确是“缺失”了，有点惭愧啊。</p><p>最早，我用的是Windows+VC自带的工程文件；后来转到Linux开发，用的是Boost的构建工具b2（Boost Build v2），写的是jamfile；再后来又定制开发Nginx，用的是Nginx自成体系的Shell config。</p><p>你看，这么多年来我就基本没正经写过Makefile，而且也没怎么用过其他的构建工具，比如cmake、scons。</p><p>所以呢，在这个GitHub项目里，我也就没有办法提供专门的Makefile，只能麻烦你在命令行上手动敲GCC的编译命令了。好在示例代码都很短很小，没有复杂的依赖关系，简简单单就能搞定，比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g++ xxx.cpp -std=c++14 -o a.out</span></span></code></pre></div><p>这里需要注意的是参数“ <strong>-std=c++14</strong>”，它告诉编译器，在处理C++代码的时候使用C++14标准，而不是11/17/20。</p><p>手敲命令还是挺麻烦的，所以，我在源码文件里还用注释的形式给出了编译命令，你可以直接拷贝粘贴使用，希望能够给你带来一点点的方便。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Copyright (c) 2020 by Chrono</span></span>
<span class="line"><span>//</span></span>
<span class="line"><span>// g++ test.cpp -std=c++11 -o a.out;./a.out</span></span>
<span class="line"><span>// g++ test.cpp -std=c++14 -o a.out;./a.out</span></span>
<span class="line"><span>// g++ test.cpp -std=c++14 -I../common -o a.out;./a.out</span></span></code></pre></div><p>在目录“section0”里，有一个最基本的示例程序，如果你能够正确地编译并运行，就说明实验环境搭建成功了。</p><p>在我的虚拟机里，这个程序的输出是（使用-std=c++14）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>c++ version = 201402</span></span>
<span class="line"><span>gcc version = 5.4.0 20160609</span></span>
<span class="line"><span>gcc major = 5</span></span>
<span class="line"><span>gcc minor = 4</span></span>
<span class="line"><span>gcc patch = 0</span></span>
<span class="line"><span>libstdc++ = 20160609</span></span></code></pre></div><p>显示使用的是C++14标准，GCC版本是5.4.0，标准库版本是20160609。</p><p>当然，如果你是写Makefile的高手，欢迎你给这个项目提Pull Request，让其他同学都能用make来轻松地编译代码。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>作为正式开课前的“热身工作”，今天我介绍了课程使用的实验环境，简单小结一下：</p><ol><li>我们选择的操作系统是Linux，具体是Ubuntu 16.04，也可以是更新的版本。</li><li>我们选择的编译器是GCC，最低要求是4.6或者4.8，推荐使用5.4或者更高的版本。</li><li>使用虚拟机软件搭建环境最方便，完全“自主可控”，推荐使用免费的VirtualBox。</li><li>GitHub上有配套的示例代码和参考资料，可以下载后编译验证环境是否搭建成功。</li></ol><p>那么，行动起来吧，下节课让我们在Linux上愉快地一起“玩耍”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%97%E5%89%91%E9%94%8B%E7%9A%84C%2B%2B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/231445/a130365df3f983716977b2e816df7c42.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%97%E5%89%91%E9%94%8B%E7%9A%84C%2B%2B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/231445/a130365df3f983716977b2e816df7c42.jpg" alt=""></a></p>`,53)])])}const g=e(p,[["render",i]]);export{h as __pageData,g as default};
